/** Metadata related to a proposed change */
export type CoreProposedChange = CoreNode & CoreTaskTarget & {
  __typename: 'CoreProposedChange';
  approved_by: NestedPaginatedCoreGenericAccount;
  comments: NestedPaginatedCoreChangeComment;
  /** None */
  description: Maybe<TextAttribute>;
  /** Name of the branch to merge changes into (required) */
  destination_branch: Maybe<TextAttribute>;
  display_label: Maybe<Scalars['String']['output']>;
  /** Human friendly identifier */
  hfid: Maybe<Array<Scalars['String']['output']>>;
  /** Unique identifier */
  id: Scalars['String']['output'];
  /** Whether the proposed change is still a draft */
  is_draft: Maybe<CheckboxAttribute>;
  member_of_groups: NestedPaginatedCoreGroup;
  /** None (required) */
  name: Maybe<TextAttribute>;
  rejected_by: NestedPaginatedCoreGenericAccount;
  reviewers: NestedPaginatedCoreGenericAccount;
  /** Name of the branch containing the changes (required) */
  source_branch: Maybe<TextAttribute>;
  /** Current state of the proposed change */
  state: Maybe<TextAttribute>;
  subscriber_of_groups: NestedPaginatedCoreGroup;
  threads: NestedPaginatedCoreThread;
  /** Total number of comments on this proposed change */
  total_comments: Maybe<NumberAttribute>;
  validations: NestedPaginatedCoreValidator;
};


